import { test } from 'node:test';
import assert from 'node:assert/strict';
import { get } from '../get.js';
const o = { a: { b: [{ c: 1 }, { c: 0 }], n: null }, items: ['x', 'y', 'z'] };
test('paths', () => { assert.equal(get(o, 'a.b[0].c'), 1); assert.equal(get(o, 'items[2]'), 'z'); assert.equal(get(o, 'a.b[1].c', 9), 0); });
test('null kept', () => assert.equal(get(o, 'a.n', 'fb'), null));
test('missing', () => { assert.equal(get(o, 'a.q.r', 'fb'), 'fb'); assert.equal(get(o, 'items[9]', 'fb'), 'fb'); assert.equal(get(o, 'a.n.x', 'fb'), 'fb'); assert.equal(get(o, 'zz'), undefined); });

solution.get.js:
export function get(obj, path, fallback) {
  const keys = path.replace(/\[(\d+)\]/g, '.$1').split('.').filter(Boolean);
  let cur = obj;
  for (const k of keys) {
    if (cur === null || cur === undefined || !(k in Object(cur))) return fallback;
    cur = cur[k];
  }
  return cur;
}
